#!/usr/bin/env node
/* Targeted rebuild of the three chrome-bearing core bundles after the
 * commend removal (fe/uniform-shell-20261012, CEO directive 2026-10-12):
 *   core/bundle-core.js, core/bundle-core-slr.js, core/bundle-footer-chrome.js
 * File lists are evaluated from the real build/bundle-core.js config
 * (CORE_FILES + the footer-chrome list + the documented bundle-core-slr
 * composition), sources are read from the target tree (site/v1.4.3 by
 * default — the shipped tree), concatenated with the canonical header,
 * minified with the repo terser (--compress --mangle --toplevel, same as
 * build/bundle-core.js), and parse-checked before writing.
 * Usage: node scripts/rebuild-uniform-shell-bundles.js [tree]
 *   tree = path relative to repo root holding a v1.4.3 dir layout
 *          (default: site). Pass "" for the root build tree. */
'use strict';
var fs = require('fs');
var path = require('path');
var cp = require('child_process');

var ROOT = path.join(__dirname, '..');
var TREE = process.argv[2] === undefined ? 'site' : process.argv[2];
var V143 = path.join(ROOT, TREE, 'v1.4.3');
var TERSER = path.join(ROOT, 'node_modules', '.bin', 'terser');

/* --- extract a top-level "var NAME = [" ... "]" literal from the config --- */
function extractArray(src, marker) {
  var i = src.indexOf(marker);
  if (i === -1) { console.error('marker not found: ' + marker); process.exit(1); }
  var start = src.indexOf('[', i), d = 0, j = start;
  for (; j < src.length; j++) {
    if (src[j] === '[') d++;
    if (src[j] === ']') { d--; if (!d) break; }
  }
  var out;
  eval('out = ' + src.slice(start, j + 1));
  return out;
}

var cfg = fs.readFileSync(path.join(ROOT, 'build', 'bundle-core.js'), 'utf8');
var CORE_FILES = extractArray(cfg, 'var CORE_FILES = ');
var FOOTER_CHROME = extractArray(cfg, "'core/bundle-footer-chrome':");

/* Site-tree divergence (pre-existing, verified 2026-10-12): 46-weave-spine
 * was registered in build/bundle-core.js by the WS-C weave merge
 * (f701aa0c) but never mirrored into the site tree and is absent from the
 * shipped site bundles. Rebuilding the site tree must reproduce shipped
 * behavior, so it is skipped there — shipping it is a separate decision.
 * The root build tree carries the file and keeps it. */
var SITE_SKIP = { 'core/46-weave-spine.js': true };
if (TREE === 'site') {
  var before = CORE_FILES.length;
  CORE_FILES = CORE_FILES.filter(function (f) { return !SITE_SKIP[f]; });
  if (CORE_FILES.length !== before) console.log('site tree: skipped unshipped silo(s) per SITE_SKIP');
}

var BUNDLES = {
  'core/bundle-core': CORE_FILES.slice(),
  'core/bundle-core-slr': ['core/00-bus.js', 'core/07-slr-db-data.js'].concat(CORE_FILES.slice(1)),
  'core/bundle-footer-chrome': FOOTER_CHROME.slice()
};

Object.keys(BUNDLES).forEach(function (name) {
  var files = BUNDLES[name];
  var out = [];
  out.push('/* PF v1.4.3 ' + path.basename(name) + '.js — concatenated bundle, generated by build/bundle-core.js.');
  out.push('   DO NOT EDIT. Regenerate with: node build/bundle-core.js [--debug]');
  out.push('   Contains: ' + files.join(', '));
  out.push('   Each file keeps its own PF.skip() kill switch (?pf_off=<silo>). */');
  files.forEach(function (f) {
    var p = path.join(V143, f);
    if (!fs.existsSync(p)) { console.error('BUNDLE FAIL: missing ' + p); process.exit(1); }
    out.push('\n/* ===== ' + f + ' ===== */');
    out.push(fs.readFileSync(p, 'utf8'));
    out.push(';');
  });
  var raw = out.join('\n');
  var final = cp.execSync(TERSER + ' --compress --mangle --toplevel', {
    input: raw, maxBuffer: 100 * 1024 * 1024
  }).toString();
  var dest = path.join(V143, name + '.js');
  fs.writeFileSync(dest, final);
  try { cp.execSync(process.execPath + ' --check ' + dest, { stdio: 'pipe' }); }
  catch (e) { console.error(name + ' failed node --check'); process.exit(1); }
  console.log((TREE || '(root)') + '/' + name + '.js: ' + files.length + ' files, ' + final.length + ' B — OK');
});
console.log('Chrome bundles rebuilt for tree: ' + (TREE || '(root)'));
